using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace MinMax;

public static class RangeCalculator
{
    /// <summary>
    /// Returns the minimum and maximum values in <paramref name="values"/>.
    /// Uses SIMD vectorization for high throughput on large spans.
    /// </summary>
    public static (float Min, float Max) FindMinMax(ReadOnlySpan<float> values)
    {
        if (values.Length == 0)
            throw new ArgumentException("Span must not be empty.");

        if (Vector256.IsHardwareAccelerated && values.Length >= Vector256<float>.Count * 2)
        {
            return FindMinMax256(values);
        }

        if (Vector128.IsHardwareAccelerated && values.Length >= Vector128<float>.Count * 2)
        {
            return FindMinMax128(values);
        }

        return FindMinMaxScalar(values);
    }

    private static (float Min, float Max) FindMinMax256(ReadOnlySpan<float> values)
    {
        ReadOnlySpan<Vector256<float>> vectors = MemoryMarshal.Cast<float, Vector256<float>>(values);

        var vMin = vectors[0];
        var vMax = vectors[0];

        for (int i = 1; i < vectors.Length; i++)
        {
            vMin = Vector256.Min(vMin, vectors[i]);
            vMax = Vector256.Max(vMax, vectors[i]);
        }

        // Reduce 256-bit to 128-bit
        var lo = vMin.GetLower();
        var hi = vMin.GetUpper();
        var min128 = Vector128.Min(lo, hi);

        lo = vMax.GetLower();
        hi = vMax.GetUpper();
        var max128 = Vector128.Max(lo, hi);

        // Reduce 128-bit to scalar
        float min = HorizontalMin(min128);
        float max = HorizontalMax(max128);

        // Handle remaining elements not covered by vector width
        int processed = vectors.Length * Vector256<float>.Count;
        for (int i = processed; i < values.Length; i++)
        {
            if (values[i] < min) min = values[i];
            if (values[i] > max) max = values[i];
        }

        return (min, max);
    }

    private static (float Min, float Max) FindMinMax128(ReadOnlySpan<float> values)
    {
        ReadOnlySpan<Vector128<float>> vectors = MemoryMarshal.Cast<float, Vector128<float>>(values);

        var vMin = vectors[0];
        var vMax = vectors[0];

        for (int i = 1; i < vectors.Length; i++)
        {
            vMin = Vector128.Min(vMin, vectors[i]);
            vMax = Vector128.Max(vMax, vectors[i]);
        }

        float min = HorizontalMin(vMin);
        float max = HorizontalMax(vMax);

        int processed = vectors.Length * Vector128<float>.Count;
        for (int i = processed; i < values.Length; i++)
        {
            if (values[i] < min) min = values[i];
            if (values[i] > max) max = values[i];
        }

        return (min, max);
    }

    private static (float Min, float Max) FindMinMaxScalar(ReadOnlySpan<float> values)
    {
        float min = values[0];
        float max = values[0];
        for (int i = 1; i < values.Length; i++)
        {
            if (values[i] < min) min = values[i];
            if (values[i] > max) max = values[i];
        }
        return (min, max);
    }

    private static float HorizontalMin(Vector128<float> v)
    {
        // Shuffle and reduce: 4 floats → 1 min
        var shuf = Vector128.Shuffle(v, Vector128.Create(2, 3, 0, 1));
        v = Vector128.Min(v, shuf);
        shuf = Vector128.Shuffle(v, Vector128.Create(1, 0, 3, 2));
        v = Vector128.Min(v, shuf);
        return v.ToScalar();
    }

    private static float HorizontalMax(Vector128<float> v)
    {
        var shuf = Vector128.Shuffle(v, Vector128.Create(2, 3, 0, 1));
        v = Vector128.Max(v, shuf);
        shuf = Vector128.Shuffle(v, Vector128.Create(1, 0, 3, 2));
        v = Vector128.Max(v, shuf);
        return v.ToScalar();
    }
}

